                typeBtns.forEach(b => {
                    b.classList.remove('text-black');
                    b.classList.add('text-gray-500');
                });
                e.target.classList.remove('text-gray-500');
                e.target.classList.add('text-black');

                if (type === 'delivery') {
                    toggleBg.style.transform = 'translateX(calc(100% + 4px))';
                    pickupResults.classList.add('hidden');
                    deliveryResults.classList.remove('hidden');
                } else {
                    toggleBg.style.transform = 'translateX(0)';
                    pickupResults.classList.remove('hidden');
                    deliveryResults.classList.add('hidden');
                }
            });
        });

        // Search Input interaction
        const searchInput = document.getElementById('store-search');
        const suggestions = document.getElementById('search-suggestions');

        searchInput.addEventListener('input', (e) => {
            if (e.target.value.length > 0) {
                suggestions.classList.remove('hidden');
            } else {
                suggestions.classList.add('hidden');
            }
        });

        // Hide suggestions when clicking outside
        document.addEventListener('click', (e) => {
            if (!searchInput.contains(e.target) && !suggestions.contains(e.target)) {
                suggestions.classList.add('hidden');
            }
        });

